/** Shape of src/server/gacha/catalog.json (generated by scripts/gacha). */

export type HairKey =
    | "black" | "brown" | "blonde" | "red" | "orange" | "pink" | "purple"
    | "blue" | "green" | "white" | "silver" | "grey" | "multicolour";

export interface CatalogCharacter {
    id: number;
    name: string;
    nameNative: string | null;
    alternative: string[];
    gender: string | null;
    age: string | null;
    role: "MAIN" | "SUPPORTING";
    favourites: number;
    image: string;
    siteUrl: string;
    hair: { key: HairKey; raw: string } | null;
    /** "field" = AniList "Hair:" label, "description" = prose ("long pink hair"). */
    hairSource?: "field" | "description" | null;
    /** Hair text that did not map to a key (gaps report only). */
    hairUnparsed?: string | null;
    occupation: string | null;
    quote: string | null;
    silhouette: string | null;
}

export interface CatalogAnime {
    id: number;
    titleRomaji: string;
    titleEnglish: string | null;
    titleNative: string | null;
    cover: string;
    coverColor: string | null;
    popularity: number;
    setCode: string;
    siteUrl: string;
    characters: CatalogCharacter[];
}

export interface Catalog {
    generatedAt: string;
    source: string;
    imageNote: string;
    anime: CatalogAnime[];
}
